Repair the complete CommonJS source below. `renderTokens(tokens)` must accept an array containing strings or objects with exactly the required string property `emphasis` (additional properties may be ignored). Invalid input must throw `TypeError`. Escape `&`, `<`, `>`, double quotes, and single quotes in all text. Plain strings are emitted directly after escaping; emphasis objects are emitted as matching `<em>...</em>` elements. Preserve input order, return an empty string for an empty array, and do not mutate the array or its objects. Export exactly the function.

```javascript
function escapeText(value) {
  return value.replace(/[&<>"']/g, (character) => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;'
  })[character]);
}

function renderTokens(tokens) {
  if (!Array.isArray(tokens)) throw new TypeError('tokens must be an array');

  return tokens.map((token) => {
    if (typeof token === 'string') return escapeText(token);
    if (token !== null && typeof token === 'object' && typeof token.emphasis === 'string') {
      return `<em>${escapeText(token.emphasis)}</strong>`;
    }
    throw new TypeError('Invalid token');
  }).join('');
}

module.exports = renderTokens;
```

