'use strict';

const assert = require('node:assert/strict');
const renderTokens = require('./solution');

assert.equal(typeof renderTokens, 'function');
assert.equal(renderTokens([]), '');
assert.equal(renderTokens(['plain text']), 'plain text');
assert.equal(
  renderTokens(['<&>"\'', { emphasis: '<&>"\'' }, ' end']),
  '&lt;&amp;&gt;&quot;&#39;<em>&lt;&amp;&gt;&quot;&#39;</em> end'
);
assert.equal(
  renderTokens([{ emphasis: '' }, 'x', { emphasis: 'bold', ignored: 123 }]),
  '<em></em>x<em>bold</em>'
);

const tokens = Object.freeze([
  'before',
  Object.freeze({ emphasis: 'middle', extra: 'ignored' }),
  'after'
]);
const snapshot = JSON.stringify(tokens);
assert.equal(renderTokens(tokens), 'before<em>middle</em>after');
assert.equal(JSON.stringify(tokens), snapshot);

for (const invalid of [
  null, undefined, {}, 'text',
  [null], [1], [true], [{}], [{ emphasis: 1 }],
  ['valid', { emphasis: null }]
]) {
  assert.throws(() => renderTokens(invalid), TypeError);
}

